const cache = new InMemoryCache({
  typePolicies: {
    Product: {
      keyFields: ['sku'], // Use SKU instead of id
      fields: {
        price: {
          read(_, { readField }) {
            // Modify price before returning
            const price = readField('price');
            return price ? price * 1.1 : 0; // Add tax
          },
        },
      },
    },
  },
});
